问题描述 (详细报错代码):
ods_sap_单位换算系数有极端数值是有业务场景吗？,zhsxs精度要重新调整，部分有数的数据被截取：SELECT meinh_f, meinh_t, umrez, umren, umrez/umren AS calculated_factor, zhsxs
FROM ods.ods_sap_erp_zhone_unit_conversion_get_df
WHERE umren = 0 OR umrez/umren > 1000 OR umrez/umren < 0.001;

解决方案（记录提交脚本的版本号）:
-- 1. 仅建空表（列定义自动与源表一致）
CREATE TABLE ods.test20260105_ods_sap_bpc_zhone_get_dimension_attribute_entity_df
LIKE ods.ods_sap_bpc_zhone_get_dimension_attribute_entity_df;
-- 2. 灌数据
INSERT INTO ods.test20260105_ods_sap_bpc_zhone_get_dimension_attribute_entity_df
SELECT * FROM ods.ods_sap_bpc_zhone_get_dimension_attribute_entity_df;

-- 1. 仅建空表（列定义自动与源表一致）
